SELECT r.order_id,r.request_id,a.attempt_id,a.attempt_no,a.config_revision,a.started_at,x.route_id,x.partner_id,p.enabled,x.valid_from,x.valid_until,CASE WHEN x.route_id IS NULL THEN 'missing' WHEN (SELECT COUNT(*) FROM routes c WHERE c.shipper_id=r.shipper_id AND c.revision=a.config_revision AND c.valid_from<=a.started_at AND (c.valid_until IS NULL OR a.started_at<c.valid_until))>1 THEN 'ambiguous' WHEN x.valid_from>a.started_at OR (x.valid_until IS NOT NULL AND a.started_at>=x.valid_until) THEN 'expired' WHEN p.enabled=0 THEN 'disabled' ELSE 'effective' END AS diagnosis FROM requests r JOIN attempts a ON a.request_id=r.request_id LEFT JOIN routes x ON x.shipper_id=r.shipper_id AND x.revision=a.config_revision LEFT JOIN partners p ON p.partner_id=x.partner_id WHERE r.order_id=@order_id ORDER BY a.attempt_no,x.route_id
